const esEjecutadoDirectamente = process.argv[1]?.endsWith("proteusSerialBridge.js");
if (esEjecutadoDirectamente) {
    const bridge = new ProteusSerialBridge().iniciar();

    process.on("SIGINT", () => {
        bridge.detener();
        process.exit(0);
    });
}

